// ---------------------------------------------------------------------------
//  measurement-db — the curated evaluation-data bank that torch_measure
//  models are estimated from. The coverage totals below are AUTO-COMPUTED from
//  benchmark-cards.json (generated by
//  scripts/render_website/generate_benchmark_gallery.py),
//  so they stay in sync with the published benchmarks and never need manual
//  updating. Source of truth: the public benchmark dirs in
//  github.com/aims-foundations/measurement-db.
// ---------------------------------------------------------------------------

import benchmarkCardsRaw from "@/content/generated/benchmark-cards.json";
import modelTimelineRowsRaw from "@/content/generated/model-timeline.json";
import { hiddenBenchmarkSet } from "@/content/curated/hidden-benchmarks";

// The single point where hidden benchmarks leave the site: every card
// consumer below (shelves, coverage totals, detail-page params, chart shelf
// lists, timeline) derives from this filtered array, so a slug in
// hidden-benchmarks.ts is absent from all of them at once. The asset proxy
// enforces the same list for the underlying files.
const benchmarkCards = benchmarkCardsRaw.filter(
  (c) => !hiddenBenchmarkSet.has(c.slug),
);

// ---------------------------------------------------------------------------
//  Shelves
// ---------------------------------------------------------------------------

// A benchmark's SHELF is who produced the response value, which is a different
// question from its domain (see the note in benchmark-gallery-client.tsx: "a
// benchmark's domain is a filter, not its shelf"). Everything listed here is
// scored by a judgment — a person's, another model's, or a reward model's —
// rather than by a programmatic verifier, so the numbers carry the judge's
// disagreement as well as the subject's ability. Several also need the pairwise
// response-matrix format, which the automatic shelf never uses.
//
// Hand-maintained: benchmark-cards.json is regenerated wholesale by
// generate_benchmark_gallery.py, so a slug list here survives a rebuild where a card field
// would not. Adding a slug that isn't published is harmless — it simply won't
// match a card.
//
// This list is declared before the coverage comparison because it defines the
// scoring-provenance split between its two component rows.
export const judgedBenchmarkSlugs: readonly string[] = [
  // the response is a human rating
  "arena_140k",
  "prompt_to_leaderboard",
  "sorrybench",
  // the response is a developer's in-session acceptance of the agent's answer,
  // read off the following prompt by an LLM judge
  "swe_chat",
  // the response is an LLM judge's score
  "alpacaeval",
  "arena_hard",
  "biggen",
  "mtbench",
  "tengu",
  "wildbench",
  "writingbench",
  // the judge or reward model IS the subject under test
  "judgebench",
  "preference_dissection",
  "rewardbench",
  "rewardbench2",
];

const judgedSet = new Set(judgedBenchmarkSlugs);

// Bank totals summed from the generated per-benchmark counts. The gallery generator
// writes items + responses on every card; we just aggregate and format here.
const bankCards = benchmarkCards as ReadonlyArray<{
  slug: string;
  items: number;
  responses: number;
}>;

// The two shelves, partitioned once. `automaticCards` is the complement of the
// judged list above and the source of `automaticBenchmarkSlugs`; likewise,
// `judgedCards` drives the judgment-scored shelf's optional summary data.
const automaticCards = bankCards.filter((c) => !judgedSet.has(c.slug));
const judgedCards = bankCards.filter((c) => judgedSet.has(c.slug));

function compactCount(n: number): string {
  if (n >= 1e9) return `${(n / 1e9).toFixed(1)}B`;
  if (n >= 1e6) return `${(n / 1e6).toFixed(1)}M`;
  if (n >= 1e3) return `${Math.round(n / 1e3)}K`;
  return `${n}`;
}

export type ShelfStat = { value: string; label: string };

export type DatabaseTotal = {
  key: "benchmarks" | "items" | "subjects" | "responses";
  label: string;
  value: string;
};

function coverageCounts(cards: typeof bankCards) {
  return {
    benchmarks: `${cards.length}`,
    items: compactCount(cards.reduce((sum, card) => sum + card.items, 0)),
    responses: compactCount(
      cards.reduce((sum, card) => sum + card.responses, 0),
    ),
  };
}

/** The three headline counts for one shelf, formatted for the stat row. The
 *  response label differs per shelf because the two shelves mean different
 *  things by a "response" — a verifier's decision vs. a judgment. */
function shelfStats(
  cards: typeof bankCards,
  responseLabel: string,
): readonly ShelfStat[] {
  const counts = coverageCounts(cards);
  return [
    { value: counts.benchmarks, label: "Benchmarks curated" },
    { value: counts.items, label: "Items" },
    { value: counts.responses, label: responseLabel },
  ];
}

/** The automatically scored shelf. */
export const automaticShelfStats = shelfStats(
  automaticCards,
  "Model × item responses",
);

/** The judgment-scored shelf. */
export const judgedShelfStats = shelfStats(judgedCards, "Judged responses");

/** Bank-wide totals. Because `bankCards` has already passed through the hidden
 *  benchmark filter, these describe exactly what a visitor can browse. */
export const bankStats = shelfStats(bankCards, "Responses");

type ModelTimelineRow = { benchmarks: readonly string[] };

// model-timeline.json has one row per canonical normalized_name, the bank's
// cross-benchmark de-duplication key for named AI subjects. Intersecting each
// row's benchmark list with the visible cards counts the distinct canonically
// named AI subjects represented in the catalog. Subjects without a
// normalized_name are intentionally omitted because they cannot be reliably
// de-duplicated. Do not sum each card's `models`: that repeats systems seen in
// several benchmarks and can include human participants.
const visibleBenchmarkSet = new Set(bankCards.map((card) => card.slug));
const uniqueAiSubjectCount = (
  modelTimelineRowsRaw as ReadonlyArray<ModelTimelineRow>
).filter((subject) =>
  subject.benchmarks.some((slug) => visibleBenchmarkSet.has(slug)),
).length;
const bankCounts = coverageCounts(bankCards);

/** The four catalog-entrance totals, derived from the same checked-in website
 *  snapshot and hidden-benchmark filter as the galleries. */
export const databaseTotals: readonly DatabaseTotal[] = [
  { key: "benchmarks", value: bankCounts.benchmarks, label: "Benchmarks" },
  { key: "items", value: bankCounts.items, label: "Items" },
  {
    key: "subjects",
    value: compactCount(uniqueAiSubjectCount),
    label: "AI subjects",
  },
  { key: "responses", value: bankCounts.responses, label: "Responses" },
];

