// The category ids ARE the raw `domain` vocabulary from benchmarks.parquet,
// one-to-one (kept verbatim, underscores and all). Must stay in lockstep with
// DOMAIN_ORDER in scripts/render_website/generate_benchmark_gallery.py.
export type BenchmarkCategoryId =
  | "safety"
  | "cybersecurity"
  | "medicine"
  | "law"
  | "finance"
  | "mathematics"
  | "software_engineering"
  | "ml_engineering"
  | "agents_and_tool_use"
  | "science"
  | "multilingual"
  | "cultural"
  | "education"
  | "preference"
  | "reward_modeling"
  | "nlp_task"
  | "knowledge"
  | "reasoning"
  | "general";

export type Benchmark = {
  slug: string;
  name: string;
  /** Every domain this benchmark maps to, most-specific first (a benchmark can
   *  belong to several — AlgoTune is both math and coding). The first entry is
   *  its primary category, used for the accent color. */
  categories: BenchmarkCategoryId[];
  /** One-line, display-ready summary (not the raw build-script description). */
  description: string;
  license: string;
  /** Upstream code / data source. */
  code: string;
  /** Reference paper or blog post. */
  paper: string;
  /** Thumbnail under /public/benchmarks, or null to render a generated
   *  per-benchmark thumbnail. Set via benchmark-overrides.json. */
  image: string | null;
  /** How the thumbnail fills its frame: "cover" for banners/screenshots,
   *  "contain" for logos and diagrams that shouldn't be cropped. */
  fit: "cover" | "contain";
  /** Distinct subjects (models / agents / reward models) evaluated in the
   *  bank's matrix for this benchmark. Computed from the published parquet. */
  models: number;
  /** Distinct evaluation items in the bank's matrix for this benchmark. */
  items: number;
  /** Upstream release date — "YYYY-MM", "YYYY", or null when unknown. Drives
   *  the release-timeline chart. */
  releaseDate: string | null;
  /** True iff upstream released per-(model, item) responses (granularity
   *  "item" in benchmarks.parquet). Drives the "item-level responses released"
   *  tag and gallery filter; item-bank-only benchmarks (granularity
   *  "aggregate"/"not_released") carry no tag. */
  itemResponses: boolean;
  /** Optional tri-state result from benchmark_saturation.py: true = saturated,
   *  false = not saturated, null = not analyzed or inconclusive. Drives the
   *  "Saturation status" tag on cards and detail pages. */
  saturation: boolean | null;
  /** Institutions of the reference paper's first two authors (deduped), from
   *  benchmark-affiliations.json
   *  (scripts/render_website/generate_benchmark_affiliations.py).
   *  `logo` points under /public/institutions, or null → initials chip.
   *  The whole field is null until the affiliation lookup has run. */
  institutions: { name: string; logo: string | null }[] | null;
};

export type BenchmarkCategory = {
  id: BenchmarkCategoryId;
  label: string;
  blurb: string;
  /** Brand hex used for the category accent + generated thumbnails. */
  color: string;
};

