// Gallery cards — GENERATED from the published parquet files by
// scripts/render_website/generate_benchmark_gallery.py (merged with the curated
// benchmark-overrides.json). Regenerate with
// `python3 scripts/render_website/generate_benchmark_gallery.py cards`. Do NOT hand-edit; change the
// overrides file (category / image / fit) instead.
export const benchmarks: readonly Benchmark[] =
  benchmarkCards as unknown as readonly Benchmark[];

/**
 * Everything scored by a programmatic verifier — the complement of
 * `judgedBenchmarkSlugs`, declared at the top of this file alongside the
 * coverage summaries that count this same shelf.
 */
export const automaticBenchmarkSlugs: readonly string[] = automaticCards.map(
  (c) => c.slug,
);

/**
 * The judged shelf as PUBLISHED — `judgedBenchmarkSlugs` filtered to the cards
 * actually in the bank. The hand list may name unpublished slugs (harmless for
 * the gallery, which simply won't match a card), but the chart pipeline treats
 * an unknown slug as a fatal coverage gap (chart-marginals.ts), so the
 * section's charts compose from this list.
 */
export const publishedJudgedBenchmarkSlugs: readonly string[] = judgedCards.map(
  (c) => c.slug,
);

// ---------------------------------------------------------------------------
//  Lookups
// ---------------------------------------------------------------------------

export function getBenchmark(slug: string): Benchmark | undefined {
  return benchmarks.find((b) => b.slug === slug);
}

export function getBenchmarkCategory(
  id: BenchmarkCategoryId,
): BenchmarkCategory | undefined {
  return benchmarkCategories.find((c) => c.id === id);
}
